#include <nlohmann/json.hpp>
#include <cstdint>
#include <cassert>
#include <iostream>

enum class book_id : uint64_t;
enum class small_id : uint32_t;
enum class signed_id : int64_t;

using json = nlohmann::json;

int main()
{
    const book_id large_id{book_id(uint64_t(1) << 63)};
    json j = large_id;
    std::cout << j.dump() << std::endl;
    assert(j > 0u);
    assert(j.dump() == "9223372036854775808");
    assert(j.is_number_unsigned());

    const book_id max_id{book_id(0xFFFFFFFFFFFFFFFFULL)};
    json j2 = max_id;
    std::cout << j2.dump() << std::endl;
    assert(j2.is_number_unsigned());
    assert(j2.dump() == "18446744073709551615");

    const small_id s{small_id(0xFFFFFFFFu)};
    json j3 = s;
    std::cout << j3.dump() << std::endl;
    assert(j3.is_number_unsigned());
    assert(j3.dump() == "4294967295");

    const signed_id neg{signed_id(-2)};
    json j4 = neg;
    std::cout << j4.dump() << std::endl;
    assert(j4.is_number_integer());
    assert(j4.dump() == "-2");

    std::cout << "all ok" << std::endl;
    return 0;
}

